"""Tests for the compact crashlab evidence package."""
# Some portions generated by Codex

import gzip
import hashlib
import tempfile
import unittest
from pathlib import Path

from package_ci_artifact import package_ci_evidence


class CiArtifactPackageTests(unittest.TestCase):
    def test_all_running_trials_preserve_images_exact_payloads_schedules_and_cut_traces(self):
        from running_contract import RUNNING_TRIALS
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary) / "crashlab"
            output = Path(temporary) / "upload"
            for trial in RUNNING_TRIALS:
                results = root / "campaigns" / trial / "results"
                preserved = results / "pre-recovery-image"
                preserved.mkdir(parents=True)
                (preserved / "data.raw").write_bytes(bytes(4096))
                for name in ("running-1-attempt.tsv", "running-1-returned.json", "actual-running-ready.json",
                             "actual-automatic-fault-schedule.json", "actual-writer-nbd-events.jsonl"):
                    (results / name).write_text(trial + "\n")
            manifest = package_ci_evidence(root, output)
            self.assertEqual(len(manifest["crash_images"]), 4)
            for trial in RUNNING_TRIALS:
                for name in ("running-1-attempt.tsv", "running-1-returned.json", "actual-running-ready.json",
                             "actual-automatic-fault-schedule.json", "actual-writer-nbd-events.jsonl"):
                    self.assertEqual((output / "campaigns" / trial / "results" / name).read_text(), trial + "\n")

    def test_compact_package_keeps_crash_image_and_witness_but_excludes_working_disks(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary) / "crashlab"
            output = Path(temporary) / "upload"
            results = root / "campaigns/namespace/results"
            preserved = results / "pre-recovery-image"
            preserved.mkdir(parents=True)
            image = (b"\x00" * 8192) + b"LMDB crash image" + (b"\x00" * 4096)
            (preserved / "data.raw").write_bytes(image)
            (results / "actual-campaign-report.json").write_text('{"result":"PUBLIC_ORACLE_PASS"}\n',
                                                                 encoding="utf-8")
            (results / "actual-namespace-witness.tsv").write_text("namespace\tex:kept\n", encoding="utf-8")
            working_data = root / "campaigns/namespace/data/data.raw"
            working_data.parent.mkdir(parents=True)
            working_data.write_bytes(b"regenerable working image")
            qemu_overlay = root / "campaigns/namespace/qemu/writer-os.qcow2"
            qemu_overlay.parent.mkdir(parents=True)
            qemu_overlay.write_bytes(b"regenerable overlay")
            guest = root / "guest"
            guest.mkdir()
            (guest / "provision-serial.log").write_text("guest boot complete\n", encoding="utf-8")
            (guest / "ubuntu-base.qcow2").write_bytes(b"regenerable OS image")
            maven = root / "maven/surefire-reports"
            maven.mkdir(parents=True)
            (maven / "TEST-LmdbCrashRecoveryTest.xml").write_text("<testsuite/>\n", encoding="utf-8")
            preflight = root / "kvm-preflight/result.txt"
            preflight.parent.mkdir(parents=True)
            preflight.write_text("KVM_PASS\n", encoding="utf-8")
            (root / "host-classpath.txt").write_text("exact build classpath\n", encoding="utf-8")

            manifest = package_ci_evidence(root, output)

            image_gzip = output / "campaigns/namespace/results/pre-recovery-image/data.raw.gz"
            self.assertEqual(gzip.decompress(image_gzip.read_bytes()), image)
            self.assertEqual(manifest["crash_images"][0]["original_sha256"],
                             hashlib.sha256(image).hexdigest())
            self.assertEqual(manifest["crash_images"][0]["package_path"],
                             "campaigns/namespace/results/pre-recovery-image/data.raw.gz")
            self.assertLess(image_gzip.stat().st_size, len(image))
            self.assertFalse((output / "campaigns/namespace/results/pre-recovery-image/data.raw").exists())
            self.assertFalse((output / "campaigns/namespace/data/data.raw").exists())
            self.assertFalse((output / "campaigns/namespace/qemu/writer-os.qcow2").exists())
            self.assertFalse((output / "guest/ubuntu-base.qcow2").exists())
            self.assertEqual((output / "campaigns/namespace/results/actual-campaign-report.json")
                             .read_text(encoding="utf-8"), '{"result":"PUBLIC_ORACLE_PASS"}\n')
            self.assertEqual((output / "campaigns/namespace/results/actual-namespace-witness.tsv")
                             .read_text(encoding="utf-8"), "namespace\tex:kept\n")
            for relative in (
                "guest/provision-serial.log",
                "maven/surefire-reports/TEST-LmdbCrashRecoveryTest.xml",
                "kvm-preflight/result.txt",
                "host-classpath.txt",
                "artifact-manifest.json",
            ):
                self.assertTrue((output / relative).is_file(), relative)

    def test_early_failure_keeps_controller_logs_and_image_checksums(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary) / "crashlab"
            output = Path(temporary) / "upload"
            campaigns = root / "campaigns"
            campaigns.mkdir(parents=True)
            (campaigns / "ci-campaign-failure.json").write_text('{"stage":"qemu-start"}\n',
                                                                  encoding="utf-8")
            (campaigns / "ci-campaign-command-plan.json").write_text('{"commands":[]}\n',
                                                                       encoding="utf-8")
            (campaigns / "ci-campaign-summary.json").write_text('{"campaigns":[]}\n',
                                                                  encoding="utf-8")
            runner_log = campaigns / "runner-logs/campaign-runner.log"
            runner_log.parent.mkdir()
            runner_log.write_text("QEMU failed before guest boot\n", encoding="utf-8")
            qemu_dir = campaigns / "namespace/qemu"
            qemu_dir.mkdir(parents=True)
            (qemu_dir / "seed.log").write_text("seed image prepared\n", encoding="utf-8")
            (qemu_dir / "seed.qcow2").write_bytes(b"binary seed image")
            image_dir = root / "guest/images"
            image_dir.mkdir(parents=True)
            (image_dir / "SHA256SUMS").write_text("deadbeef  ubuntu-base.img\n", encoding="utf-8")
            (image_dir / "ubuntu-base.sha256").write_text("deadbeef\n", encoding="utf-8")
            (image_dir / "ubuntu-base.img").write_bytes(b"binary guest image")

            manifest = package_ci_evidence(root, output)

            for relative in (
                "campaigns/ci-campaign-failure.json",
                "campaigns/ci-campaign-command-plan.json",
                "campaigns/ci-campaign-summary.json",
                "campaigns/runner-logs/campaign-runner.log",
                "campaigns/namespace/qemu/seed.log",
                "guest/images/SHA256SUMS",
                "guest/images/ubuntu-base.sha256",
            ):
                self.assertTrue((output / relative).is_file(), relative)
                self.assertIn(relative, manifest["preserved_files"])
            self.assertFalse((output / "campaigns/namespace/qemu/seed.qcow2").exists())
            self.assertFalse((output / "guest/images/ubuntu-base.img").exists())

    def test_package_refuses_preexisting_destination(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary) / "crashlab"
            root.mkdir()
            output = Path(temporary) / "upload"
            output.mkdir()
            with self.assertRaises(FileExistsError):
                package_ci_evidence(root, output)


if __name__ == "__main__":
    unittest.main(verbosity=2)
